{
  "source_context": [
    {
      "section": "V1",
      "lyrics": [
        "鳥はなんで空をとべるの？",
        "猫はなんでずっとねてるの？",
        "君はどんな今日を生きるの？",
        "ぜんぶ ぜんぶ ぜんぶ",
        "さがしにゆこう"
      ]
    },
    {
      "section": "V2",
      "lyrics": [
        "朝はなんで僕を照らすの？",
        "夜はなんで寂しくなるの？",
        "かなしいことははんぶんこ",
        "できたらいいのにね"
      ]
    },
    {
      "section": "B1",
      "lyrics": [
        "笑ったり悩んでみたり",
        "この広い世界のすみっこで",
        "僕らでうちゅうのふしぎ",
        "解き明かしてみよう"
      ]
    },
    {
      "section": "C1",
      "lyrics": [
        "星はなんで輝いてるの",
        "雲はどうして空を泳ぐの",
        "人はなんで夢を描くの",
        "答えなんてないのかな"
      ]
    },
    {
      "section": "D1",
      "lyrics": [
        "いつかこんなちいさなうたは",
        "きみはきっとわすれちゃうけど",
        "ぼくはずっとおぼえているよ",
        "おとなになってもね"
      ]
    },
    {
      "section": "V3",
      "lyrics": [
        "今日はどんな話をしよう？",
        "君とどんな歌を歌おう？",
        "誰もまだ知らない花も"
      ]
    },
    {
      "section": "O1",
      "lyrics": [
        "ぜんぶ ぜんぶ ぜんぶ",
        "さがしにゆこう",
        "ぜんぶ ぜんぶ ぜんぶ",
        "さがしにゆこう"
      ]
    }
  ],
  "section": "D1",
  "phrases": [
    {
      "id": "D1-01",
      "ja": "いつかこんなちいさなうたは",
      "budget": {
        "min": 12,
        "max": 12
      },
      "pattern": [
        3,
        2,
        3,
        4
      ]
    },
    {
      "id": "D1-02",
      "ja": "きみはきっとわすれちゃうけど",
      "budget": {
        "min": 12,
        "max": 12
      },
      "pattern": [
        3,
        2,
        3,
        4
      ]
    },
    {
      "id": "D1-03",
      "ja": "ぼくはずっとおぼえているよ",
      "budget": {
        "min": 12,
        "max": 12
      },
      "pattern": [
        3,
        2,
        3,
        4
      ]
    },
    {
      "id": "D1-04",
      "ja": "おとなになってもね",
      "budget": {
        "min": 9,
        "max": 9
      },
      "pattern": [
        4,
        2,
        3
      ]
    }
  ],
  "candidates": [
    {
      "label": "A",
      "phrases": [
        {
          "id": "D1-01",
          "zh": "总有一天这样的小小歌谣"
        },
        {
          "id": "D1-02",
          "zh": "你一定会把它忘掉哟"
        },
        {
          "id": "D1-03",
          "zh": "可我会一直记着它哦"
        },
        {
          "id": "D1-04",
          "zh": "就算长大成人了喔"
        }
      ]
    },
    {
      "label": "B",
      "phrases": [
        {
          "id": "D1-01",
          "zh": "终有一天这小小歌谣"
        },
        {
          "id": "D1-02",
          "zh": "你一定会把它忘掉"
        },
        {
          "id": "D1-03",
          "zh": "我却会永远记得牢"
        },
        {
          "id": "D1-04",
          "zh": "即使长大成人后"
        }
      ]
    },
    {
      "label": "C",
      "phrases": [
        {
          "id": "D1-01",
          "zh": "某一天 这首 小小的 歌会飘散"
        },
        {
          "id": "D1-02",
          "zh": "你以后 也许 会忘得 干干净净"
        },
        {
          "id": "D1-03",
          "zh": "可我会 一直 都记得 清清楚楚"
        },
        {
          "id": "D1-04",
          "zh": "变成大人 以后 也记得"
        }
      ]
    },
    {
      "label": "D",
      "phrases": [
        {
          "id": "D1-01",
          "zh": "有一天 这首 小小的 歌会飘远"
        },
        {
          "id": "D1-02",
          "zh": "你大概 哪天 哼起它 却记不得"
        },
        {
          "id": "D1-03",
          "zh": "我却会 一直 记得它 从哪儿来"
        },
        {
          "id": "D1-04",
          "zh": "长成大人 以后 也不忘"
        }
      ]
    }
  ]
}

